// leading normal comment
export function compute(a: number, b: number, flag: boolean, input: string): number {
  const ratio = (a + b) / 2;
  const obj = { return: 10 };
  const half = obj.return / 2;
  let hits = 0;
  if (flag) /alpha\/beta[\/]gamma/gi.test(input) && (hits += 1);
  while (false) /never/.test(input);
  const nonNull = input!;
  const len = nonNull.length / 2;
  const msg = `top ${`mid ${ratio + half} // keep`} tail /* keep */`;
  /*#__PURE__*/ console.log(msg);
  return len + hits;
}

export function asiCheck(x: number): number {
  let y = x;
  let z = 1;
  y
  ++z;
  return y + z;
}
